mapper.select:
select  from documents d join purchase_orders p on p.document_id=d.id join suppliers s on s.document_id=p.supplier_id
where d.type='PURCHASE_ORDER' and d.deleted='0'
and (#{params.supplyGlobal}=true or d.creator_id=#{params.currentUserId} or p.buyer_id=#{params.currentUserId})
and p.supplier_id=#{supplierId}and p.buyer_id=#{buyerId}
and d.approval_status=#{approvalStatus}
and d.number like concat('%',#{number},'%') order by d.update_time desc
